mapper.insert:
/* QueryID=kkdugi.core.i18n.mapper.I18nMessageMapper.insert */
INSERT INTO kkdugi_i18n_msg (msg_cd, lang_cd, msg_val, reg_dtm, reg_id)
VALUES (#{msgCode}, #{langCode}, #{msgText}, #{createdAt}, #{creatorId})

mapper.update:
/* QueryID=kkdugi.core.i18n.mapper.I18nMessageMapper.update */
UPDATE kkdugi_i18n_msg
SET msg_val = #{msgText},
    upd_dtm = #{updatedAt},
    upd_id  = #{updaterId}
WHERE msg_cd = #{msgCode}
  AND lang_cd = #{langCode}

mapper.delete:
